                            location: 'jam/package-one'
                        }
                    ]);
                    var p = path.resolve(
                        that.project_dir,
                        'jam/package-one/package.json'
                    );
                    var content = fs.readFileSync(p);
                    var pkg = JSON.parse(content.toString());
                    test.equal(pkg.version, '0.0.2');
                    cb();
                });
